-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/marts/int_quality_events.sql, analytics/dbt/models/marts/int_quality_cells.sql. Do not edit.
-- Internal: the events the hospital quality measures count, one row per measure and counted unit (a stay, or for the
-- diabetes measure each HbA1c result of a person), with the day that puts it in a period. mart_quality_monthly and
-- mart_quality_period aggregate these, so every period and the pooled "all" source use the same definitions:
--   readmission_30d            index stay = hospital admission with a discharge; meets = readmitted within 30 days
--                              (gold_encounter_summary.readmitted_30d). Dated by discharge. All cause; planned
--                              readmissions and deaths in hospital are not excluded (unlike CMS HRRP).
--   los_mean_days, los_median_days  the same index stays; amount = length of stay in days. Dated by discharge.
--   ed_los_median_hours        emergency department visits that went home (kind emergency visit) with an end; amount =
--                              hours from arrival to departure (in the spirit of CMS OP 18). Dated by departure.
--   diabetes_a1c_under_8       HEDIS style, not certified: every numeric HbA1c result (LOINC 4548-4, 17856-6 or 4549-2,
--                              unit %, no comparator) of a person in the diabetes_type2 cohort; meets = under 8 percent.
--                              A period counts each person once, by their latest result in it. Dated by the result.
--   potassium_abnormal_on_admission  hospital admissions with a potassium result (key lab potassium) of the same record
--                              in the 24 hours from admission; meets = the first such result is under 3.5 or over
--                              5.0 mmol/L. Dated by admission.
CREATE OR REPLACE TABLE int_quality_events AS
WITH enc AS (
    SELECT * FROM fact_encounter
),
index_stays AS (
    SELECT * FROM enc WHERE is_admission AND discharge_at IS NOT NULL AND length_of_stay_days IS NOT NULL
),
diabetic_people AS (
    SELECT DISTINCT k.patient_sk
    FROM gold_cohort_members m
    JOIN int_patient_key k ON k.patient_id = m.patient_id
    WHERE m.cohort = 'diabetes_type2'
),
potassium AS (
    SELECT
        e.encounter_sk, e.patient_sk, e.source, e.admit_at, r.value_num,
        ROW_NUMBER() OVER (PARTITION BY e.encounter_sk ORDER BY r.effective_at, r.lab_result_sk) AS rn
    FROM enc e
    JOIN fact_lab_result r
      ON r.patient_record_sk = e.patient_record_sk
     AND r.effective_at >= e.admit_at
     AND DATEDIFF('minute', e.admit_at, r.effective_at) < 24 * 60
    JOIN seed_key_labs k ON k.loinc = r.loinc AND k.lab = 'potassium'
    WHERE e.is_admission AND r.comparator IS NULL
)
SELECT 'readmission_30d' AS measure_id, source, patient_sk, encounter_sk AS unit_sk, encounter_sk AS event_sk,
       CAST(discharge_at AS DATE) AS event_date, discharge_at AS event_at, readmitted_30d AS meets,
       CAST(NULL AS DOUBLE) AS amount
FROM index_stays
UNION ALL
SELECT 'los_mean_days', source, patient_sk, encounter_sk, encounter_sk,
       CAST(discharge_at AS DATE), discharge_at, CAST(NULL AS BOOLEAN), length_of_stay_days
FROM index_stays
UNION ALL
SELECT 'los_median_days', source, patient_sk, encounter_sk, encounter_sk,
       CAST(discharge_at AS DATE), discharge_at, CAST(NULL AS BOOLEAN), length_of_stay_days
FROM index_stays
UNION ALL
SELECT 'ed_los_median_hours', source, patient_sk, encounter_sk, encounter_sk,
       CAST(discharge_at AS DATE), discharge_at, CAST(NULL AS BOOLEAN), length_of_stay_hours
FROM enc
WHERE encounter_kind = 'emergency visit' AND discharge_at IS NOT NULL AND length_of_stay_hours IS NOT NULL
UNION ALL
SELECT 'diabetes_a1c_under_8', r.source, r.patient_sk, r.patient_sk, r.lab_result_sk,
       r.effective_date, r.effective_at, CASE WHEN r.value_num < 8.0 THEN TRUE ELSE FALSE END, r.value_num
FROM fact_lab_result r
JOIN diabetic_people d ON d.patient_sk = r.patient_sk
WHERE r.loinc IN ('4548-4', '17856-6', '4549-2') AND r.comparator IS NULL AND r.unit = '%'
UNION ALL
SELECT 'potassium_abnormal_on_admission', source, patient_sk, encounter_sk, encounter_sk,
       CAST(admit_at AS DATE), admit_at, CASE WHEN value_num < 3.5 OR value_num > 5.0 THEN TRUE ELSE FALSE END, value_num
FROM potassium
WHERE rn = 1;

-- Internal: every quality measure aggregated, before any suppression, for each period (month, quarter, year, all_time)
-- and source (mimic, synthea, hl7v2, and all: the sources pooled). One row per period_type, period_start, measure and
-- source that has a denominator. Holds the small counts the marts hide: for building them only, not for BI.
--   numerator    proportion: units that meet the measure; mean: the total (days or hours); median: NULL
--   denominator  units counted (stays, or people for the diabetes measure: each person once per period, by their latest
--                result in it; in "all" a person linked across sources is one person)
--   statistic    mean or median; NULL for proportions
-- all_time runs over the whole calendar of dim_date (period_start its first day).
CREATE OR REPLACE TABLE int_quality_cells AS
WITH calendar AS (
    SELECT MIN(calendar_date) AS first_day FROM dim_date
),
dated AS (
    SELECT e.*, d.month_start_date, d.quarter_start_date, d.year_start_date
    FROM int_quality_events e
    JOIN dim_date d ON d.calendar_date = e.event_date
),
by_source AS (
    SELECT measure_id, source, patient_sk, unit_sk, event_sk, event_at, meets, amount,
           month_start_date, quarter_start_date, year_start_date
    FROM dated
    UNION ALL
    SELECT measure_id, 'all', patient_sk, unit_sk, event_sk, event_at, meets, amount,
           month_start_date, quarter_start_date, year_start_date
    FROM dated
),
by_period AS (
    SELECT 'month' AS period_type, month_start_date AS period_start, b.* FROM by_source b
    UNION ALL
    SELECT 'quarter', quarter_start_date, b.* FROM by_source b
    UNION ALL
    SELECT 'year', year_start_date, b.* FROM by_source b
    UNION ALL
    SELECT 'all_time', c.first_day, b.* FROM by_source b CROSS JOIN calendar c
),
-- one row per counted unit in each cell: the latest event (only the diabetes measure has several per unit)
units AS (
    SELECT p.*,
           ROW_NUMBER() OVER (PARTITION BY period_type, period_start, measure_id, source, unit_sk
                              ORDER BY event_at DESC, event_sk DESC) AS rn
    FROM by_period p
)
SELECT
    u.period_type,
    u.period_start,
    u.measure_id,
    u.source,
    MIN(u.quarter_start_date)                                                           AS quarter_start_date,
    MIN(u.year_start_date)                                                              AS year_start_date,
    CASE m.kind
        WHEN 'proportion' THEN CAST(SUM(CASE WHEN u.meets THEN 1 ELSE 0 END) AS DOUBLE)
        -- summed as DECIMAL, so the total does not depend on row order
        WHEN 'mean' THEN CAST(SUM(CAST(u.amount AS DECIMAL(18, 2))) AS DOUBLE)
    END                                                                                 AS numerator,
    COUNT(*)                                                                            AS denominator,
    CASE m.kind
        WHEN 'mean' THEN CAST(SUM(CAST(u.amount AS DECIMAL(18, 2))) AS DOUBLE) / COUNT(*)
        WHEN 'median' THEN CAST(MEDIAN(u.amount) AS DOUBLE)
    END                                                                                 AS statistic
FROM units u
JOIN seed_quality_measures m ON m.measure_id = u.measure_id
WHERE u.rn = 1
GROUP BY u.period_type, u.period_start, u.measure_id, u.source, m.kind;
